const name = `projects/${s.projectId}/databases/(default)/documents/profiles/${candidate.version}`;
return [{ json: {
  adopt: verdict.adopt,
  reason: verdict.reason,
  current: metrics.current,
  candidate,
  commit: { writes: [updateWrite(name, candidate, { merge: false })] },
} }];

